import '../css/app.css';
import { createApp } from 'vue';
import { createRouter, createWebHistory } from 'vue-router';

// Import the demo login component
import LoginDemo from '@/Pages/Auth/LoginDemo.vue';

// Create router
const router = createRouter({
  history: createWebHistory(),
  routes: [
    { path: '/', component: LoginDemo, name: 'Home' },
    { path: '/login', component: LoginDemo, name: 'Login' },
  ]
});

// Create and mount app
const app = createApp({
  template: '<router-view />'
});

app.use(router);
app.mount('#app');
